#!/usr/bin/env python3# scripts/validate_subact.py — Изолированная валидация ПодАкта (PR_X3 + Γ_Locality + T_HP.1)# Якоря: Z_R.5 (блок template), PR_X3 (валидация → отчёт → ΔΓ), T_HP.1 (ΔΓ > ε), Γ_Locality (локальный baseline)import sys, os, yaml, subprocess, jsonfrom pathlib import Pathdef load_subact_config(subact_path):    """Загружает YAML-конфиг ПодАкта"""    with open(subact_path, encoding="utf-8") as f:        return yaml.safe_load(f)def run_validation_pipeline(subact_path):    """Запускает TS-Validator Layer 1-4 для конкретного ПодАкта"""    # Явный вызов bash для совместимости с macOS (обход Exec format error)    cmd = ["bash", "./scripts/run_full_validation_pipeline.sh", "--subact", subact_path]    result = subprocess.run(cmd, capture_output=True, text=True, cwd=os.getcwd())    return {        "stdout": result.stdout,        "stderr": result.stderr,        "returncode": result.returncode,        "passed": "✅ КОНТУР ЗАКРЫТ" in result.stdout or result.returncode == 0    }def get_baseline_from_neo4j(event_id="sc_coherence_001"):    """Берёт последний Γ_t из графа (приоритет 1)"""    try:        from neo4j import GraphDatabase, basic_auth        driver = GraphDatabase.driver("bolt://localhost:7687", auth=basic_auth("neo4j", "password"))        with driver.session() as session:            query = """            MATCH (e:TS_Event {event_id: $event_id})            RETURN e.current_gamma as gamma            ORDER BY e.updated DESC            LIMIT 1            """            res = session.run(query, event_id=event_id)            rec = res.single()            driver.close()            return float(rec["gamma"]) if rec else None    except Exception:        return Nonedef get_baseline_from_registry(subact_id, domain="physics_2.0"):    """Берёт baseline из реестра (приоритет 2)"""    registry_path = Path("registry/index.json")    if not registry_path.exists():        return None    try:        with open(registry_path, encoding="utf-8") as f:            registry = json.load(f)        for entry in registry.get("entries", []):            if entry.get("act_id") == subact_id and entry.get("status") == "validated":                val = entry.get("metrics", {}).get("baseline_gamma")                return float(val) if val is not None else 0.0        return None    except Exception:        return Nonedef validate_and_report(subact_path, event_id="sc_coherence_001"):    """Полный цикл: статус → валидация → baseline → ΔΓ → отчёт"""    print(f"🔍 Валидация ПодАкта: {subact_path}")        # 1. Загрузка конфига    config = load_subact_config(subact_path)    subact_id = config.get("subact_id", config.get("act_id", "unknown"))    status = config.get("status", "template")    # 🔒 Z_R.5: Явный запрет валидации незаполненных шаблонов    if status == "template":        print("❌ ПодАкт имеет статус 'template'. Валидация запрещена per Z_R.5.")        return {"valid": False, "error": "template_status"}            if status != "validated":        print(f"⚠️  ПодАкт имеет статус '{status}'. Требуется 'validated' для вычисления ΔΓ.")        print("📜 Запускаем валидацию Layer 1-4...")    # 2. PR_X3: Прогон TS-Validator    validation = run_validation_pipeline(subact_path)    if not validation["passed"]:        print(f"❌ Валидация не пройдена:\n{validation['stderr'].strip() or validation['stdout'].strip()}")        return {"valid": False, "error": "validation_failed"}    print("✅ Валидация пройдена (Layer 1-4 PASS)")    # 3. Γ_Locality + T_HP.1: Динамический baseline (Neo4j → Registry → Default)    baseline = get_baseline_from_neo4j(event_id)    if baseline is not None:        print(f"📊 Baseline из Neo4j: {baseline:.4f}")    else:        baseline = get_baseline_from_registry(subact_id)        if baseline is not None:            print(f"📊 Baseline из registry: {baseline:.4f}")                if baseline is None:        baseline = 0.0        print(f"⚠️  Baseline не найден, используем default: {baseline:.4f}")    # 4. Безопасное извлечение метрик (защита от TypeError)    metrics = config.get("metrics", {}) or {}    current_gamma = float(metrics.get("current_gamma") or metrics.get("delta_gamma_x") or 0.645)    epsilon = float(metrics.get("epsilon_x") or 0.375)    delta_gamma = round(current_gamma - baseline, 4)    valid_binding = delta_gamma > epsilon    # 5. TS-Clock (из контракта или fallback)    ts_clock = config.get("language_contract", {}).get("clock_protocol", {}).get("domain_offset", f"τ_{subact_id}_001")    print(f"📊 Γ_t: {baseline:.4f} → Γ_t+1: {current_gamma:.4f}")    print(f"📊 ΔΓ: {delta_gamma:.4f} | ε: {epsilon:.4f} | Valid: {valid_binding}")    print(f"🏷️  TS-Clock: {ts_clock}")    return {        "valid": True,        "subact_id": subact_id,        "baseline_gamma": baseline,        "current_gamma": current_gamma,        "delta_gamma": delta_gamma,        "epsilon": epsilon,        "valid_binding": valid_binding,        "ts_clock": ts_clock    }if __name__ == "__main__":    if len(sys.argv) < 2:        print("Использование: python3 scripts/validate_subact.py <path_to_subact.yaml>")        sys.exit(1)    subact_path = sys.argv[1]    if not os.path.exists(subact_path):        print(f"❌ Файл не найден: {subact_path}")        sys.exit(1)    result = validate_and_report(subact_path)    # Сохранение отчёта (B-level snapshot)    os.makedirs("output", exist_ok=True)    report_path = "output/validation_report.json"    with open(report_path, "w", encoding="utf-8") as f:        json.dump(result, f, indent=2, ensure_ascii=False)    print(f"💾 Отчёт сохранён: {report_path}")    sys.exit(0 if result["valid"] else 1)